    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==2]
    # Find the pair of markers sharing a row or column that define the main spine.
    pairs=[]
    for i,(r,c) in enumerate(pts):
        for rr,cc in pts[i+1:]:
            if r==rr or c==cc: pairs.append((abs(r-rr)+abs(c-cc),r,c,rr,cc))
    _,r,c,rr,cc=max(pairs)
    # Color the spine and connect each remaining marker perpendicularly to it.
    if r==rr:
        for x in range(min(c,cc),max(c,cc)+1):
            if g[r][x]==0:g[r][x]=3
        for pr,pc in pts:
            if pr!=r:
                for y in range(min(pr,r),max(pr,r)+1):
                    if g[y][pc]==0:g[y][pc]=3
    else:
        for y in range(min(r,rr),max(r,rr)+1):
            if g[y][c]==0:g[y][c]=3
        for pr,pc in pts:
            if pc!=c:
                for x in range(min(pc,c),max(pc,c)+1):
                    if g[pr][x]==0:g[pr][x]=3
    return g
'''
